// ===========================================================================//	CGLUTApp.h				   		©1997 Mikl—s Fazekas. All rights reserved.// ===========================================================================// Application class for GLUT.// 1997/09/06 Added TGLUTIDList. #ifndef _H_CGLUTApp#define _H_CGLUTApp#pragma once#include <LApplication.h>#include <UException.h>#include <TArray.h>#include <gl.h>#include <agl.h>#include "glut.h"#include "glutint.h"const MessageT  cmd_UpdateMenus			= 250;	// update the menus.// Exceptions thrown by the CGLUTApp class:enum {	err_GlutBase				=	'glut',	err_GlutBaseApp				= 	err_GlutBase+10,	err_GlutNoCurrentWindow		=	err_GlutBaseApp+0,	err_GlutNoCurrentMenu		=	err_GlutBaseApp+1,	err_GlutNoSuchWindow		=	err_GlutBaseApp+2,	err_GlutNoSuchMenu			=	err_GlutBaseApp+3};class CGLUTWindow;class CGLUTMenu;#pragma warn_hidevirtual offtemplate class TArray<CGLUTMenu*>;template class TArray<CGLUTWindow*>;#pragma warn_hidevirtual resetclass	CGLUTApp : public LApplication {public:						CGLUTApp();		// constructor	virtual 			~CGLUTApp();	// destructor				// This overrriding function performs application functions			virtual Boolean		ObeyCommand(CommandT inCommand, void* ioParam);				// This overriding function returns the status of menu items			virtual void		FindCommandStatus(CommandT inCommand,							Boolean &outEnabled, Boolean &outUsesMark,							Char16 &outMark, Str255 outName);		// This overrides the idle time	virtual void			UseIdleTime		(const EventRecord &inMacEvent);		virtual void			ShowAboutBox();		// ==================================== 	// GLUT-API functions:	// ====================================		// GLUT initialziation	int 	glutCreateWindow(char* name);	void	glutInitDisplayMode(unsigned int mode);	void 	glutInitWindowSize(int width, int height);	void	glutInitWindowPosition(int x, int y);		// Windows	void	glutSetWindowTitle(Str255 inName);	int		glutGetWindow(void);	void	glutHideWindow(void);	void	glutShowWindow(void);		// Display callbacks:	void	glutDisplayFunc(GLUTdisplayCB	inDisplayFunc);	void	glutReshapeFunc(GLUTreshapeCB	inReshapeFunc);	void	glutVisibilityFunc(GLUTvisibilityCB	inVisibilityFunc);		// Keyboard callbacks:	void	glutKeyboardFunc(GLUTkeyboardCB	inKeyboardFunc);	void	glutSpecialFunc(GLUTspecialCB	inReshapeFunc);		// Mouse callbacks:	void	glutMouseFunc(GLUTmouseCB	inMouseFunc);	void	glutMotionFunc(GLUTmotionCB	inMouseFunc);	void	glutPassiveMotionFunc(GLUTpassiveCB	inMouseFunc);	void	glutEntryFunc(GLUTentryCB inEntryFunc);		// Timing callbacks:	void	glutIdleFunc(GLUTidleCB	inIdleFunc);	void	glutTimerFunc(unsigned int inMillis,						  GLUTtimerCB inTimerFunc,						  int value);		// Other glut api:	void	glutSetCursor(int cursor);	int		glutGet(GLenum state);	void	glutSwapBuffers(void);	void 	glutPostRedisplay(void);		// Final:			// Window sub api:	void			glutDestroyWindow(							int 		inGlutID);	void			glutSetWindow(							int 		inGlutID);		// Menu	sub api:						int				glutCreateMenu(							GLUTselectCB inSelectFunc);	void			glutDestroyMenu(							int			inGlutID);	void			glutSetMenu(							int			inGlutID);		void			glutAddMenuEntry(							const char	*inName,							int			inValue);	void			glutAddSubMenu(							const char 	*inLabel,							int 		inSubMenuID);		void			glutChangeToMenuEntry(							int 		inEntry, 							const char 	*inLabel, 							int 		inValue);	void			glutChangeToSubMenu(							int 		inEntry,							const char 	*inLabel,							int 		inSubMenuID);	void			glutAttachMenu(							int 		inButton);	int				glutGetMenu();			CGLUTMenu*		FindGlutMenu(							int 		inGlutID);private:	// Returns the required pixel-fmt	AGLPixelFmt 	GetAGLPixelFormat();		// Final:	inline CGLUTWindow*		GetCurrentWindow()								{ return mCurrentWindow; }	inline void				SetCurrentWindow(								CGLUTWindow *inGLUTWindow)								{ mCurrentWindow = inGLUTWindow; }		inline CGLUTMenu*		GetCurrentMenu()								{ return mCurrentMenu; }	inline void				SetCurrentMenu(								CGLUTMenu *inGLUTMenu)								{ mCurrentMenu = inGLUTMenu; }									CGLUTWindow*			FindGlutWindow(								int 		inGlutID);	protected:	enum { kMenuListSize = 20 };	enum { kWindowListSize = 20 };		// GLUT-Default window size:	Rect	winRect;		// GLUT default window mode:	unsigned int mDisplayMode;		//ÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑ	// GLUT-Windows:	//ÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑ	CGLUTWindow 				*mCurrentWindow;	TArray<CGLUTWindow*>	mWindowList;		//ÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑ	// GLUT-Menus:	//ÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑÑ	CGLUTMenu					*mCurrentMenu;	TArray<CGLUTMenu*> 	mMenuList;		//============================	// GLUT: Application-Callbacks	//============================	GLUTidleCB		idleFunc;	virtual void		StartUp();		// overriding startup functions		//	// Default Glut Cursor:	//	GLint 	mGlutDefaultCursor;		// Statup time:	UInt32 mGlutStartTime;private:	void		DisposeGlutWindows();	void		DisposeGlutMenus();};#endif /* _H_CGLUTApp */